import numpy as np

def feature(current, candidates, tour, start):
    """Squared distance from the current city to each candidate, normalised by the farthest candidate."""
    d = candidates - current[None, :]
    sq = np.einsum('ij,ij->i', d, d)
    mx = sq.max()
    if mx <= 0:
        return np.zeros(len(candidates))
    return sq / mx

import numpy as np

def feature(current, candidates, tour, start):
    """Negated Euclidean distance from the current city, scaled by the mean distance to all candidates."""
    d = np.linalg.norm(candidates - current, axis=1)
    return -d / (d.mean() + 1e-12)

import numpy as np

def feature(current, candidates, tour, start):
    """Cosine of the angle between the last travel step and the step to each candidate."""
    if len(tour) >= 2:
        direction = tour[-1] - tour[-2]
    else:
        direction = np.zeros(2)
    n = np.linalg.norm(direction)
    if n < 1e-12:
        return np.zeros(len(candidates))
    u = direction / n
    vecs = candidates - current
    nrm = np.linalg.norm(vecs, axis=1)
    return (vecs @ u) / (nrm + 1e-12)

import numpy as np

def feature(current, candidates, tour, start):
    """Negated distance from each candidate to its nearest unvisited neighbour, normalised by the max (isolated cities preferred)."""
    k = len(candidates)
    D = np.linalg.norm(candidates[:, None, :] - candidates[None, :, :], axis=2)
    np.fill_diagonal(D, np.inf)
    nearest = D.min(axis=1)
    mx = nearest.max()
    if mx <= 0 or not np.isfinite(mx):
        return np.zeros(k)
    return -nearest / (mx + 1e-12)

