import numpy as np

def feature(current, candidates, tour, start):
    """Nearest-neighbour distance of each candidate, normalised by the max, but measured only against the other unvisited cities excluding the current city's own nearest-neighbour relation, i.e. min distance to any unvisited city other than itself and the current city."""
    k = len(candidates)
    if k < 2:
        return np.zeros(k)
    diff = candidates[:, None, :] - candidates[None, :, :]
    dist = np.sqrt(np.einsum('ijk,ijk->ij', diff, diff))
    np.fill_diagonal(dist, np.inf)
    # exclude the current city from the neighbourhood: measure isolation among the
    # remaining unvisited set only, so the current position does not anchor the min
    nn = dist.min(axis=1)
    mx = nn.max()
    if mx <= 0:
        return np.zeros(k)
    return nn / mx

