import numpy as np

def feature(current, candidates, tour, start):
    """Negated (distance current->candidate + min distance to start over other unvisited candidates), max-normalised."""
    k = candidates.shape[0]
    if k < 2:
        return np.zeros(k)
    d_cur = np.linalg.norm(candidates - current, axis=1)
    d_st = np.linalg.norm(candidates - start, axis=1)
    srt = np.sort(d_st)
    mn_excl = np.full(k, srt[0])
    mn_excl[np.argmin(d_st)] = srt[1]
    value = -(d_cur + mn_excl)
    return value / (np.abs(value).max() + 1e-12)

import numpy as np

def feature(current, candidates, tour, start):
    """Negated distance from current to each candidate divided by that candidate's nearest-neighbour distance among the remaining candidates, normalised by the max absolute ratio."""
    k = candidates.shape[0]
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    if k < 2:
        nn = np.zeros(k)
    else:
        D = np.linalg.norm(candidates[:, None, :] - candidates[None, :, :], axis=2)
        np.fill_diagonal(D, np.inf)
        nn = D.min(axis=1)
    r = d_cur / (nn + 1e-9)
    return -r / (np.abs(r).max() + 1e-12)

import numpy as np

def feature(current, candidates, tour, start):
    """Negated (distance from current to candidate + candidate's second-nearest unvisited city distance), normalised by max abs."""
    k = candidates.shape[0]
    if k == 0:
        return np.zeros(0)
    # pairwise distances among candidates
    diff = candidates[:, None, :] - candidates[None, :, :]
    D = np.sqrt(np.sum(diff * diff, axis=2))
    np.fill_diagonal(D, np.inf)
    if k >= 2:
        s2 = np.partition(D, 1, axis=1)[:, 1]
    else:
        s2 = np.zeros(k)
    dcur = np.sqrt(np.sum((candidates - current) ** 2, axis=1))
    v = -(dcur + s2)
    m = np.max(np.abs(v))
    if m <= 0:
        return np.zeros(k)
    return v / m

import numpy as np

def feature(current, candidates, tour, start):
    """Negated distance from current to each candidate divided by (1 + nn_c/R), normalised by max abs."""
    k = candidates.shape[0]
    if k == 0:
        return np.zeros(0)
    # R = distance from current to nearest unvisited city
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    R = np.min(d_cur)
    # nn_c = each candidate's nearest other unvisited city
    if k > 1:
        diff = candidates[:, None, :] - candidates[None, :, :]
        D = np.linalg.norm(diff, axis=2)
        np.fill_diagonal(D, np.inf)
        nn_c = np.min(D, axis=1)
    else:
        nn_c = np.zeros(k)
    denom = 1.0 + nn_c / (R + 1e-9)
    v = -d_cur / denom
    m = np.max(np.abs(v))
    if m <= 0:
        return np.zeros(k)
    return v / m

import numpy as np

def feature(current, candidates, tour, start):
    """Fraction of other unvisited cities within R of each candidate, R = median nearest-neighbour distance of the remaining set."""
    k = candidates.shape[0]
    if k < 2:
        return np.zeros(k)
    diff = candidates[:, None, :] - candidates[None, :, :]
    D = np.sqrt((diff ** 2).sum(axis=2))
    np.fill_diagonal(D, np.inf)
    nn = D.min(axis=1)
    R = np.median(nn)
    if not np.isfinite(R) or R <= 0:
        return np.zeros(k)
    count = (D <= R).sum(axis=1)
    return count / k

import numpy as np

def feature(current, candidates, tour, start):
    """Negated distance from each candidate to its k-th nearest unvisited neighbour, normalised by the max."""
    k = len(candidates)
    if k < 2:
        return np.zeros(k)
    D = np.linalg.norm(candidates[:, None, :] - candidates[None, :, :], axis=2)
    np.fill_diagonal(D, np.inf)
    D.sort(axis=1)
    # k-th nearest neighbour (index k-2 after sorting, since diagonal inf is last)
    n = min(k - 1, 4)
    d = D[:, n - 1]
    mx = d.max()
    if mx <= 0:
        return np.zeros(k)
    return -d / mx

import numpy as np

def feature(current, candidates, tour, start):
    """Squared distance from current to each candidate, but only the component along the direction of travel, normalised by the max absolute projection."""
    # direction of travel: from previous city to current (or from start to current at the first step)
    if len(tour) >= 2:
        prev = tour[-2]
    else:
        prev = start
    v = current - prev
    n = np.linalg.norm(v)
    if n <= 1e-12:
        # no defined direction: fall back to squared distance normalisation
        d = candidates - current[None, :]
        sq = np.einsum('ij,ij->i', d, d)
        mx = sq.max()
        if mx <= 0:
            return np.zeros(len(candidates))
        return sq / mx
    u = v / n
    d = candidates - current[None, :]
    proj = d @ u
    mx = np.abs(proj).max()
    if mx <= 0:
        return np.zeros(len(candidates))
    return proj / mx

import numpy as np

def feature(current, candidates, tour, start):
    """Negated exact optimal cost of completing the tour from each candidate (endgame only, k<=6)."""
    k = len(candidates)
    if k > 6:
        return np.zeros(k)

    P = np.vstack([current[None, :], candidates])  # row 0 = current, rows 1..k = candidates
    diff = P[:, None, :] - P[None, :, :]
    D = np.sqrt((diff ** 2).sum(-1))  # (k+1, k+1)
    ds = np.sqrt(((candidates - start[None, :]) ** 2).sum(-1))  # (k,)

    # all permutations of range(k), shape (k!, k), via insertion recursion
    def perms(items):
        if len(items) <= 1:
            return [list(items)]
        out = []
        for i in range(len(items)):
            rest = items[:i] + items[i + 1:]
            for p in perms(rest):
                out.append([items[i]] + p)
        return out

    p = np.array(perms(list(range(k))), dtype=int)  # (k!, k)

    cost = D[0, p[:, 0] + 1].copy()
    for i in range(k - 1):
        cost += D[p[:, i] + 1, p[:, i + 1] + 1]
    cost += ds[p[:, -1]]

    # best completion cost for each candidate as the first city visited
    best = np.full(k, np.inf)
    for j in range(k):
        best[j] = cost[p[:, 0] == j].min()

    cmin = best.min()
    cmax = best.max()
    return (cmax - best) / (cmax - cmin + 1e-12)
